# 2. Comparison Operators:
a = 33
b = 10
print("Is a equal to b? :", a == b) # Equal to (will return True if both the operands are equal, otherwise it will return False)

print("Is a equal to 4? :", a == 4) # Equal to (will return True if both the operands are equal, otherwise it will return False)
print("Is a less than 3? :", a < 3) # Less than (will return True if the left operand is less than the right operand, otherwise it will return False)
print("Is a greater than 3? :", a > 3) # Greater than (will return True if the left operand is greater than the right operand, otherwise it will return False)
print("Is a less than or equal to 3? :", a <= 3) # Less than or equal to (will return True if the left operand is less than or equal to the right operand, otherwise it will return False)
print("Is a greater than or equal to 3? :", a >= 3) # Greater than or equal to (will return True if the left operand is greater than or equal to the right operand, otherwise it will return False)
print("Is a not equal to b? :", a != b) # Not equal to (will return True if both the operands are not equal, otherwise it will return False) 